package com.metaplatform.agent.action;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest; import org.springframework.test.context.TestPropertySource; import java.time.Instant; import static org.assertj.core.api.Assertions.assertThat;
@DataJpaTest @TestPropertySource(properties={"spring.flyway.enabled=false","spring.jpa.hibernate.ddl-auto=create-drop"}) class ActionProposalRepositoryTest { @Autowired ActionProposalRepository repository; @Test void crudAndCustomQueries(){ Instant now=Instant.now(); repository.save(ActionProposalEntity.builder().proposalId("p-1").runId("run-1").actionCode("ontology.do").targetObjects("[\"o\"]").parameters("{}").reason("r").evidenceRefs("[\"e\"]").riskLevel(RiskLevel.LOW).approvalRequired(false).idempotencyKey("key").status(ActionProposalStatus.PROPOSED).proposedAt(now).expiresAt(now.minusSeconds(1)).createdAt(now).updatedAt(now).build()); assertThat(repository.findById("p-1")).isPresent(); assertThat(repository.findByIdempotencyKey("key")).isPresent(); assertThat(repository.findByStatusAndExpiresAtBefore(ActionProposalStatus.PROPOSED,now)).hasSize(1); } }
